#!/usr/bin/env node
// Score a benchmark run.
//
// Usage:
//   node scripts/score.mjs <results-path> [--report <file>]
//
// <results-path> is either a single result JSON or a directory of result
// JSONs. See benchmark/results/README.md for the result format.
//
// Reads expected answers from expected/answers.json (regenerated by
// scripts/validate.mjs). Writes a Markdown report to
// results/latest-report.md by default.

import { readFileSync, readdirSync, existsSync, writeFileSync, mkdirSync, statSync } from 'node:fs';
import { join, dirname, basename, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { scoreCase, aggregateCases, DIMENSIONS } from './score-lib.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..');
const ANSWERS_FILE = join(ROOT, 'expected', 'answers.json');
const DEFAULT_REPORT = join(ROOT, 'results', 'latest-report.md');

const args = process.argv.slice(2);
const resultsPath = args[0];
if (!resultsPath) {
  console.error('usage: node scripts/score.mjs <results-path> [--report <file>]');
  process.exit(1);
}
const reportIdx = args.indexOf('--report');
const reportFile = reportIdx >= 0 ? resolve(args[reportIdx + 1]) : DEFAULT_REPORT;

if (!existsSync(ANSWERS_FILE)) {
  console.error(`expected/answers.json not found. Run: node scripts/validate.mjs`);
  process.exit(1);
}
if (!existsSync(resultsPath)) {
  console.error(`results path not found: ${resultsPath}`);
  process.exit(1);
}

const answers = JSON.parse(readFileSync(ANSWERS_FILE, 'utf8'));
const expected = answers.cases;

// --- load results -------------------------------------------------------
function loadPath(path, out) {
  const entries = readdirSync(path, { withFileTypes: true });
  for (const e of entries) {
    const full = join(path, e.name);
    if (e.isDirectory()) { loadPath(full, out); continue; }
    if (!e.name.endsWith('.json') || e.name === 'latest-report.md') continue;
    let data;
    try { data = JSON.parse(readFileSync(full, 'utf8')); }
    catch { console.error(`skip (unparseable JSON): ${full}`); continue; }
    const id = data.caseId || e.name.replace(/\.json$/, '');
    if (!expected[id]) { console.error(`skip (unknown case id ${id}): ${full}`); continue; }
    out[id] = data;
  }
  return out;
}
function loadSingleFile(path) {
  const data = JSON.parse(readFileSync(path, 'utf8'));
  const id = data.caseId;
  if (!expected[id]) throw new Error(`result file ${path} has unknown case id "${id}"`);
  return { [id]: data };
}

const isDir = statSync(resultsPath).isDirectory();
const results = isDir ? loadPath(resultsPath, {}) : loadSingleFile(resultsPath);

// --- score --------------------------------------------------------------
const notRun = Object.keys(expected).filter(id => !results[id]);
const malformed = [];
const perCase = {};

for (const [id, exp] of Object.entries(expected)) {
  const r = results[id];
  if (!r) continue;
  if (!r.output || typeof r.output !== 'object') {
    malformed.push(id);
    console.error(`skip (no "output" object): ${id}`);
    continue;
  }
  perCase[id] = { expected: exp, result: r, scored: scoreCase(exp, r) };
}

const agg = aggregateCases(expected, results);

// --- report -------------------------------------------------------------
const dimNames = DIMENSIONS.map(([n]) => n);
const dimMeans = dimNames.map((_, i) => {
  const vals = Object.values(perCase).map(c => c.scored.dims[i].score);
  return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0;
});
const totals = Object.values(perCase).map(c => c.scored.total);
const meanTotal = totals.length ? totals.reduce((a, b) => a + b, 0) / totals.length : 0;
const rawMean = Object.values(perCase).map(c => c.scored.raw)
  .reduce((a, b) => a + b, 0) / (totals.length || 1);

const fmt = x => (x === null || x === undefined) ? 'n/a' : x.toFixed(3);

const lines = [];
lines.push(`# Benchmark report`);
lines.push('');
lines.push(`- **Benchmark version:** ${answers.benchmarkVersion}`);
lines.push(`- **Results source:** ${resultsPath}`);
lines.push(`- **Generated:** ${new Date().toISOString()}`);
lines.push(`- **Cases run:** ${Object.keys(perCase).length} / ${Object.keys(expected).length}`);
if (notRun.length) lines.push(`- **Not run (${notRun.length}):** ${notRun.join(', ')}`);
if (malformed.length) lines.push(`- **Malformed (${malformed.length}):** ${malformed.join(', ')}`);
lines.push('');
lines.push(`## Overall`);
lines.push('');
lines.push(`| Metric | Value |`);
lines.push(`|---|---|`);
lines.push(`| Mean raw score (/40) | ${rawMean.toFixed(2)} |`);
lines.push(`| Mean final score (/40, after FP multiplier) | ${meanTotal.toFixed(2)} |`);
for (let i = 0; i < dimNames.length; i++) {
  lines.push(`| Mean ${dimNames[i]} (/5) | ${dimMeans[i].toFixed(2)} |`);
}
lines.push('');
lines.push(`## Finding-level aggregates`);
lines.push('');
lines.push(`| Metric | Value |`);
lines.push(`|---|---|`);
lines.push(`| TP / FP / FN / TN | ${agg.counts.TP} / ${agg.counts.FP} / ${agg.counts.FN} / ${agg.counts.TN} |`);
lines.push(`| Precision | ${fmt(agg.precision)} |`);
lines.push(`| Recall | ${fmt(agg.recall)} |`);
lines.push(`| BLOCKING TP / FP / FN | ${agg.counts.TP_B} / ${agg.counts.FP_B} / ${agg.counts.FN_B} |`);
lines.push(`| BLOCKING precision | ${fmt(agg.blockingPrecision)} |`);
lines.push(`| BLOCKING recall | ${fmt(agg.blockingRecall)} |`);
lines.push(`| Intent detection rate | ${fmt(agg.rates.intentDetection)} |`);
lines.push(`| Evidence accuracy | ${fmt(agg.rates.evidenceAccuracy)} |`);
lines.push(`| Verification accuracy | ${fmt(agg.rates.verificationAccuracy)} |`);
lines.push(`| Silence rate (NO-ISSUE) | ${fmt(agg.rates.silenceRate)} |`);
lines.push('');
lines.push(`## Per-case scores`);
lines.push('');
lines.push(`| Case | Expected | ` + dimNames.map(d => d.split(' ').map(w => w[0]).join('')).join(' | ') + ` | Raw | × | Final |`);
lines.push(`|---|---|---` + dimNames.map(() => '---').join('|') + `|---:|---:|---:|`);
for (const [id, c] of Object.entries(perCase)) {
  const exp = c.expected;
  const s = c.scored;
  const dimCells = s.dims.map(d => d.score).join(' | ');
  lines.push(`| ${id} | ${exp.severity_expected}/${exp.evidence_expected} | ${dimCells} | ${s.raw} | ×${s.multiplier.toFixed(2)} | ${s.total.toFixed(1)} |`);
}
lines.push('');

const report = lines.join('\n');
mkdirSync(dirname(reportFile), { recursive: true });
writeFileSync(reportFile, report);
console.log(report);
console.log(`\nReport written to ${reportFile}`);
